// Parse CPython bytes repr lines from stdin -> hex
import { readFileSync } from 'node:fs';
const txt = readFileSync(0, 'latin1');
for (const line of txt.split('\n')) {
  if (!line.startsWith('b')) { if (line.trim()) console.log('??', JSON.stringify(line)); continue; }
  const q = line[1];
  const body = line.slice(2, line.lastIndexOf(q));
  const out = [];
  for (let i = 0; i < body.length; i++) {
    const c = body[i];
    if (c === '\\') {
      const n = body[i+1];
      if (n === 'x') { out.push(parseInt(body.substr(i+2,2),16)); i += 3; }
      else if (n === 't') { out.push(9); i++; }
      else if (n === 'n') { out.push(10); i++; }
      else if (n === 'r') { out.push(13); i++; }
      else if (n === '\\') { out.push(0x5c); i++; }
      else if (n === "'") { out.push(0x27); i++; }
      else if (n === '"') { out.push(0x22); i++; }
      else throw new Error('unknown escape ' + n);
    } else out.push(c.charCodeAt(0));
  }
  console.log(out.map(b => b.toString(16).padStart(2,'0')).join(''), `(${out.length} bytes)`);
}
